import type { Prisma } from "@/db/generated/client";
import { z } from "zod";
import { prisma } from "@/db";

const stockResearchIdSchema = z.string().min(1, "id is required");
const userIdSchema = z.string().min(1, "userId is required");

export const stockResearchStatusSchema = z.enum([
  "PENDING",
  "RUNNING",
  "RERUNNING",
  "COMPLETED",
  "FAILED",
]);

const inputJsonSchema = z.custom<Prisma.InputJsonValue>(
  (value) => value !== undefined,
);

const stockResearchWriteSchema = z.object({
  userId: userIdSchema,
  companyName: z.string().min(1).nullable().optional(),
  symbol: z.string().min(1).nullable().optional(),
  exchange: z.string().min(1).nullable().optional(),
  isin: z.string().min(1).nullable().optional(),
  instrumentKey: z.string().min(1).nullable().optional(),
  query: z.string().min(1),
  status: stockResearchStatusSchema.optional(),
  runCount: z.number().int().min(0).optional(),
  determinerPlan: inputJsonSchema.nullable().optional(),
  report: inputJsonSchema.nullable().optional(),
  reportMarkdown: z.string().nullable().optional(),
  error: z.string().nullable().optional(),
  startedAt: z.coerce.date().nullable().optional(),
  completedAt: z.coerce.date().nullable().optional(),
});

const stockResearchPutSchema = stockResearchWriteSchema.omit({ userId: true });
const stockResearchPatchSchema = stockResearchPutSchema.partial();

export type StockResearchCreateInput = z.input<typeof stockResearchWriteSchema>;
export type StockResearchPutInput = z.input<typeof stockResearchPutSchema>;
export type StockResearchPatchInput = z.input<typeof stockResearchPatchSchema>;

function toCreateData(
  input: z.infer<typeof stockResearchWriteSchema>,
): Prisma.StockResearchCreateInput {
  return input;
}

function toUpdateData(
  input: Prisma.StockResearchUpdateInput,
): Prisma.StockResearchUpdateInput {
  return input;
}

export async function createStockResearch(input: StockResearchCreateInput) {
  return await prisma.stockResearch.create({
    data: toCreateData(stockResearchWriteSchema.parse(input)),
  });
}

export async function getStockResearchById(id: string) {
  return await prisma.stockResearch.findUnique({
    where: { id: stockResearchIdSchema.parse(id) },
  });
}

export async function getStockResearchByIdForUser(id: string, userId: string) {
  return await prisma.stockResearch.findFirst({
    where: {
      id: stockResearchIdSchema.parse(id),
      userId: userIdSchema.parse(userId),
    },
  });
}

export async function getStockResearchWithResourcesByIdForUser(
  id: string,
  userId: string,
) {
  return await prisma.stockResearch.findFirst({
    where: {
      id: stockResearchIdSchema.parse(id),
      userId: userIdSchema.parse(userId),
    },
    include: {
      resources: { orderBy: { createdAt: "asc" } },
    },
  });
}

export async function listStockResearchesByUserId(
  userId: string,
  options?: { limit?: number; status?: z.infer<typeof stockResearchStatusSchema> },
) {
  const parsedUserId = userIdSchema.parse(userId);
  const limit = options?.limit ?? 50;
  return await prisma.stockResearch.findMany({
    where: {
      userId: parsedUserId,
      ...(options?.status ? { status: options.status } : {}),
    },
    orderBy: { createdAt: "desc" },
    take: limit,
  });
}

export async function patchStockResearch(
  id: string,
  input: StockResearchPatchInput,
) {
  return await prisma.stockResearch.update({
    where: { id: stockResearchIdSchema.parse(id) },
    data: toUpdateData(
      stockResearchPatchSchema.parse(input) as Prisma.StockResearchUpdateInput,
    ),
  });
}

export async function patchStockResearchForUser(
  id: string,
  userId: string,
  input: StockResearchPatchInput,
) {
  const existing = await getStockResearchByIdForUser(id, userId);
  if (!existing) {
    return null;
  }
  return await patchStockResearch(id, input);
}

/** Mark run start: increments runCount and sets status RUNNING or RERUNNING. */
export async function markStockResearchRunStarted(id: string) {
  const existing = await getStockResearchById(id);
  if (!existing) {
    return null;
  }
  const nextStatus =
    existing.status === "COMPLETED" ||
    existing.status === "FAILED" ||
    existing.runCount > 0
      ? "RERUNNING"
      : "RUNNING";

  return await prisma.stockResearch.update({
    where: { id: stockResearchIdSchema.parse(id) },
    data: {
      status: nextStatus,
      runCount: { increment: 1 },
      startedAt: new Date(),
      completedAt: null,
      error: null,
    },
  });
}

export async function markStockResearchCompleted(
  id: string,
  input: {
    report?: Prisma.InputJsonValue | null;
    reportMarkdown?: string | null;
    determinerPlan?: Prisma.InputJsonValue | null;
  } = {},
) {
  return await prisma.stockResearch.update({
    where: { id: stockResearchIdSchema.parse(id) },
    data: {
      status: "COMPLETED",
      completedAt: new Date(),
      error: null,
      ...(input.report !== undefined ? { report: input.report } : {}),
      ...(input.reportMarkdown !== undefined
        ? { reportMarkdown: input.reportMarkdown }
        : {}),
      ...(input.determinerPlan !== undefined
        ? { determinerPlan: input.determinerPlan }
        : {}),
    },
  });
}

export async function markStockResearchFailed(id: string, error: string) {
  return await prisma.stockResearch.update({
    where: { id: stockResearchIdSchema.parse(id) },
    data: {
      status: "FAILED",
      completedAt: new Date(),
      error: z.string().min(1).parse(error),
    },
  });
}

import type { Prisma } from "@/db/generated/client";
import { z } from "zod";
import { prisma } from "@/db";

const stockResearchIdSchema = z.string().min(1, "stockResearchId is required");
const stockResearchResourceIdSchema = z.string().min(1, "id is required");
const researchSourceIdSchema = z.uuid();

export const stockResearchProviderSchema = z.enum([
  "UPSTOX",
  "SERP",
  "FIRECRAWL",
  "NEWS",
  "AI",
  "INTERNAL",
]);

export const stockResearchResourceTypeSchema = z.enum([
  "MARKET_DATA",
  "FUNDAMENTAL",
  "NEWS",
  "WEB_PAGE",
  "OPTIONS",
  "HISTORICAL",
  "SYNTHESIS",
  "OTHER",
]);

const inputJsonSchema = z.custom<Prisma.InputJsonValue>(
  (value) => value !== undefined,
);

const stockResearchResourceWriteSchema = z.object({
  stockResearchId: stockResearchIdSchema,
  provider: stockResearchProviderSchema,
  type: stockResearchResourceTypeSchema,
  title: z.string().min(1).nullable().optional(),
  url: z.string().url().nullable().optional(),
  externalId: z.string().min(1).nullable().optional(),
  content: z.string().nullable().optional(),
  rawData: inputJsonSchema.nullable().optional(),
  metadata: inputJsonSchema.nullable().optional(),
  researchSourceId: researchSourceIdSchema.nullable().optional(),
  contentHash: z.string().min(1).nullable().optional(),
});

const stockResearchResourcePutSchema = stockResearchResourceWriteSchema.omit({
  stockResearchId: true,
});
const stockResearchResourcePatchSchema =
  stockResearchResourcePutSchema.partial();

export type StockResearchResourceCreateInput = z.input<
  typeof stockResearchResourceWriteSchema
>;
export type StockResearchResourcePutInput = z.input<
  typeof stockResearchResourcePutSchema
>;
export type StockResearchResourcePatchInput = z.input<
  typeof stockResearchResourcePatchSchema
>;

function toCreateData(
  input: z.infer<typeof stockResearchResourceWriteSchema>,
): Prisma.StockResearchResourceCreateInput {
  return input;
}

function toUpdateData(
  input: Prisma.StockResearchResourceUpdateInput,
): Prisma.StockResearchResourceUpdateInput {
  return input;
}

export async function createStockResearchResource(
  input: StockResearchResourceCreateInput,
) {
  return await prisma.stockResearchResource.create({
    data: toCreateData(stockResearchResourceWriteSchema.parse(input)),
  });
}

export async function getStockResearchResourceById(id: string) {
  return await prisma.stockResearchResource.findUnique({
    where: { id: stockResearchResourceIdSchema.parse(id) },
  });
}

export async function listStockResearchResourcesByResearchId(
  stockResearchId: string,
) {
  return await prisma.stockResearchResource.findMany({
    where: { stockResearchId: stockResearchIdSchema.parse(stockResearchId) },
    orderBy: { createdAt: "asc" },
  });
}

export async function patchStockResearchResource(
  id: string,
  input: StockResearchResourcePatchInput,
) {
  return await prisma.stockResearchResource.update({
    where: { id: stockResearchResourceIdSchema.parse(id) },
    data: toUpdateData(
      stockResearchResourcePatchSchema.parse(
        input,
      ) as Prisma.StockResearchResourceUpdateInput,
    ),
  });
}

/** Idempotent insert when contentHash is set (unique per research + provider). */
export async function upsertStockResearchResourceByHash(
  input: StockResearchResourceCreateInput,
) {
  const data = stockResearchResourceWriteSchema.parse(input);
  if (!data.contentHash) {
    return await prisma.stockResearchResource.create({ data: toCreateData(data) });
  }

  const { stockResearchId, provider, contentHash, ...update } = data;
  return await prisma.stockResearchResource.upsert({
    where: {
      stockResearchId_provider_contentHash: {
        stockResearchId,
        provider,
        contentHash,
      },
    },
    create: toCreateData(data),
    update: toUpdateData(update as Prisma.StockResearchResourceUpdateInput),
  });
}

